   /**
    * Creates the provided command.
    * 
    * @param		command ${class.getCreateCommandAlias()}
    * @exception    ProcessingException
    * @exception	IllegalArgumentException
    * @return		Notebook
    */
	public Notebook createNotebook( CreateNotebookCommand command )
    throws ProcessingException, IllegalArgumentException {

		Notebook entity = new Notebook();

		try {
			// --------------------------------------
        	// validate the command
        	// --------------------------------------    	
        	NotebookValidator.getInstance().validate( command );    

            entity.setNotebookId( command.getNotebookId() );
            entity.setTitle( command.getTitle() );
            entity.setRepository( command.getRepository() );
            entity.setLanguage( command.getLanguage() );
    	    
        	// ------------------------------------------
        	// persist a new one
        	// ------------------------------------------ 
    	    entity = projector.create(entity);
    	    
			LOGGER.info( "done creating of Notebook {0} ", entity.toString() );

        }
        catch (Exception exc) {
            final String errMsg = "Unable to create Notebook - " + exc;
            LOGGER.warn(  errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }

   /**
    * Update the provided command.
    * @param		command UpdateNotebookCommand
    * @exception    ProcessingException
    * @exception  	IllegalArgumentException
    * @return		Notebook
    */
    public Notebook updateNotebook( UpdateNotebookCommand command ) 
    throws ProcessingException, IllegalArgumentException {

	    Notebook entity = new Notebook();

    	try {       

			// --------------------------------------
        	// validate 
        	// --------------------------------------    	
        	NotebookValidator.getInstance().validate( command );    

            entity.setNotebookId( command.getNotebookId() );
            entity.setTitle( command.getTitle() );
            entity.setRepository( command.getRepository() );
            entity.setWorkspace( command.getWorkspace() );
            entity.setDatasets( command.getDatasets() );
            entity.setExperiments( command.getExperiments() );
            entity.setQueries( command.getQueries() );
            entity.setLanguage( command.getLanguage() );
        	
        	// ------------------------------------------
        	// persist an existing one
        	// ------------------------------------------ 
        	entity = projector.update(entity);
    	    
			LOGGER.info( "done saving of Notebook {0} ", entity.toString() );
    	}
        catch (Exception exc) {
            final String errMsg = "Unable to save Notebook - " + exc;
            LOGGER.warn( errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
    	
    	return entity;
    }
   
